      if(!drag)return;var dy=e.clientY-drag.y0;
      if(!drag.moved&&Math.abs(dy)<5)return;
      if(!drag.moved){drag.moved=true;drag.box.classList.add('is-dragging');}
      var snapped=Math.round(dy/15)*15;
