  function openCancel(a){
    var d=dialog('<form class="sched-reason"><h2>¿Por qué se cancela?</h2><p>'+esc(patientName(a.patient_id))+' · '+esc(fmtDate(new Date(a.starts_at),{weekday:'long',day:'numeric',month:'long'}))+', '+esc(fmtTime(a.starts_at))+'</p><div class="sched-reason-chips" role="radiogroup" aria-label="Motivo">'+CANCEL_REASONS.map(function(x,i){return '<label><input type="radio" name="reason" value="'+esc(x)+'"'+(i===0?' checked':'')+'><span>'+esc(x)+'</span></label>';}).join('')+'</div><label class="sched-reason-more" hidden>Cuéntanos más<input name="more" maxlength="200" placeholder="Escribe el motivo"></label><div class="schedule-dialog-actions"><button type="button" class="btn btn-secondary" data-back>Volver</button><button type="submit" class="btn btn-danger">Cancelar cita</button></div></form>');
    var form=d.querySelector('form'),more=form.querySelector('.sched-reason-more');
    form.addEventListener('change',function(){more.hidden=form.elements.reason.value!=='Otro motivo';if(!more.hidden)form.elements.more.focus();});
    d.querySelector('[data-back]').onclick=function(){openAppointment(a);};
    form.onsubmit=function(e){e.preventDefault();var reason=form.elements.reason.value;if(reason==='Otro motivo')reason=form.elements.more.value.trim();if(reason.length<2){form.elements.more.focus();return;}transition(a,'cancelled',reason);};
  }
