  function build(){var page=el('section','pantalla schedule-page');page.id='p-agenda';page.innerHTML='<header class="schedule-head"><div><span class="schedule-eyebrow">AGENDA CLÍNICA</span><h1>Organiza tu día</h1><p>Citas, llegadas y disponibilidad.</p></div><div class="schedule-head-actions"><button class="btn btn-secondary" id="schedule-block">Bloquear horario</button><button class="btn btn-secondary" id="schedule-walkin">Llegó sin cita</button><button class="btn btn-primary" id="schedule-new">Nueva cita</button></div></header><div id="schedule-feedback"></div><section id="schedule-focus" class="schedule-focus" aria-live="polite"></section><section id="schedule-metrics" class="schedule-metrics"></section><div class="schedule-tabs"><button data-schedule-tab="calendar" aria-selected="true">Agenda</button><button data-schedule-tab="requests">Por confirmar <span id="schedule-request-count"></span></button><button data-schedule-tab="waitlist">Lista de espera <span id="schedule-waitlist-count"></span></button><button data-schedule-tab="settings">Horarios y servicios</button></div><section data-schedule-panel="calendar"><div class="schedule-toolbar"><div class="schedule-period-nav"><button id="schedule-prev" aria-label="Periodo anterior">‹</button><button id="schedule-today">Hoy</button><button id="schedule-next" aria-label="Periodo siguiente">›</button><strong id="schedule-period" aria-live="polite"><span class="sk sk-line is-lg" style="display:inline-block;width:150px;vertical-align:middle" aria-hidden="true"></span><span class="sk-sr">Cargando fechas…</span></strong></div><div class="schedule-filters"><label class="schedule-filter" for="schedule-branch"><span>Sucursal</span><select id="schedule-branch" aria-label="Filtrar sucursal"></select></label><label class="schedule-filter" for="schedule-professional"><span>Profesional</span><select id="schedule-professional" aria-label="Filtrar profesional"></select></label><div class="schedule-view-toggle" aria-label="Vista de agenda"><button data-schedule-view="month">Mes</button><button data-schedule-view="week" aria-pressed="true">Semana</button><button data-schedule-view="day">Día</button><button data-schedule-view="agenda">Lista</button></div></div></div><div id="schedule-calendar" class="schedule-calendar week"></div></section><section data-schedule-panel="requests" hidden><div class="schedule-section-title"><div><h2>Citas por confirmar</h2><p>Coordina profesional, paciente y espacio antes de crear la cita.</p></div></div><div id="schedule-requests-list"></div></section><section data-schedule-panel="waitlist" hidden><div id="schedule-waitlist" class="schedule-waitlist"></div></section><section data-schedule-panel="settings" hidden><div class="schedule-settings-grid"><article class="schedule-card"><div class="schedule-section-title"><div><h2>Servicios</h2><p>Duración y referencia operativa.</p></div><button class="btn btn-secondary" id="schedule-add-service">Agregar</button></div><div id="schedule-services-list"></div></article><article class="schedule-card"><div class="schedule-section-title"><div><h2>Horario de tu equipo</h2><p>Cuándo atiende cada profesional en cada sede.</p></div></div><div id="schedule-hours-list"></div></article></div></section><dialog id="schedule-dialog" class="schedule-dialog"></dialog>';document.querySelector('.contenido').append(page);
    page.querySelectorAll('[data-schedule-tab]').forEach(function(b){b.onclick=function(){state.tab=b.dataset.scheduleTab;renderAll();if(state.tab==='waitlist'&&window.SmylWaitlist)window.SmylWaitlist.render(document.getElementById('schedule-waitlist'),{canManage:state.canManage});};});page.querySelectorAll('[data-schedule-view]').forEach(function(b){b.onclick=function(){state.view=b.dataset.scheduleView;try{localStorage.setItem('smyl-schedule-view',state.view);}catch(e){}state.loaded=false;state.reuseStatic=true;load(true);};});function step(direction){if(state.view==='month'){state.date=new Date(state.date.getFullYear(),state.date.getMonth()+direction,1);}else state.date=plusDays(state.date,direction*(state.view==='day'?1:state.view==='agenda'?14:7));state.loaded=false;state.reuseStatic=true;load(true);}page.querySelector('#schedule-prev').onclick=function(){step(-1);};page.querySelector('#schedule-next').onclick=function(){step(1);};page.querySelector('#schedule-today').onclick=function(){state.date=startDay(new Date());state.loaded=false;state.reuseStatic=true;load(true);};page.querySelector('#schedule-branch').onchange=function(){state.branch=this.value;renderFilters();renderCalendar();renderHiddenNote();};page.querySelector('#schedule-professional').onchange=function(){state.professional=this.value;renderCalendar();};page.querySelector('#schedule-walkin').onclick=function(){openNew(null,null,null,null,{walkIn:true});};page.querySelector('#schedule-new').onclick=function(){openNew(null);};page.querySelector('#schedule-block').onclick=openBlock;page.querySelector('#schedule-add-service').onclick=openService;page.querySelector('#schedule-dialog').onclick=function(e){if(e.target===e.currentTarget)e.currentTarget.close();};}
  function consolidateServiceSettings(){var tab=document.querySelector('[data-schedule-tab="settings"]'),card=document.getElementById('schedule-services-list')?.closest('.schedule-card'),button=document.getElementById('schedule-add-service');if(tab)tab.textContent='Horarios y servicios';if(card){var title=card.querySelector('h2'),copy=card.querySelector('.schedule-section-title p');if(title)title.textContent='Servicios activos';if(copy)copy.textContent='Consulta aquí lo disponible para citas. Precios, duración y claves fiscales se administran en un solo catálogo.';}if(button){button.textContent='Abrir Servicios y tarifas';button.onclick=function(){window.ir('precios');};}}
